def design(x, mode):
    (p, n) = (np.roll(x, 1, axis=1), np.roll(x, -1, axis=1))
    if mode == 'ratio':
        return np.stack([np.ones_like(x), x + 0.15 * p - 0.3 * n - 0.22 * x * n + 0.18 * x ** 3], axis=-1)
    return np.stack([np.ones_like(x), x, p, n, x * n, x ** 3], axis=-1)

def fit(x, y, mode):
    a = design(x, mode)

    def solve(w):
        return np.stack([np.linalg.lstsq(a[:, j] * w[:, None], y[:, j] * w, rcond=None)[0] for j in range(4)])
    w = np.ones(len(x))
    c = solve(w)
    for _ in range(30):
        e = np.linalg.norm(np.einsum('nif,if->ni', a, c) - y, axis=1)
        w = 1 / np.hypot(1, e / max(0.0003, 1.5 * np.median(e)))
        c = solve(w)
    good = e < max(0.002, 8 * np.median(e))
    return (solve(good.astype(float)), good)

def _stress_map(cal):
    raw = cal['bridge_raw']
    return np.linalg.lstsq(np.column_stack([np.ones(len(raw)), raw]), cal['true_channel_loads'], rcond=None)[0].sum(axis=1)
